public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        return Collections.emptyList();
    }

    String rawPath = u.getPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return Collections.emptyList();
    }

    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }

    List<String> segments = Arrays.asList(rawPath.split("/"));
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    for (String segment : segments) {
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, standardCharset().name());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("Unsupported encoding", e);
            }
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

